(function(){'use strict';
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const n=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}),dec=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}),money=(v,currency='RUB')=>Number.isFinite(v)?n.format(v)+(currency==='RUB'?' ₽':currency?' '+currency:' · валюта не указана'):'—';
 const rules={stockout:['Нет остатка при реализации','В периоде есть реализация, текущий остаток равен нулю. Архивные SKU исключены.','Остатки'],cost:['Не заполнена себестоимость','У продававшихся SKU нет положительной текущей себестоимости. Архивные SKU исключены.','Учёт'],negative:['Отрицательные начисления','Начисления по SKU ниже нуля. Это повод разобрать удержания и корректировки, а не вывод об убытке.','Проверка'],logistics:['Логистика от 30%','Логистика составляет не менее 30% положительной реализации SKU. Порог служит фильтром для проверки.','Расходы']};
 window.PultFocusUI={create({selectFilter,selectStore,openProduct}){
  let model=null,report=null,favorites=new Set();try{const saved=JSON.parse(localStorage.getItem('pult-favorite-skus-v1'));if(Array.isArray(saved))favorites=new Set(saved.filter(x=>typeof x==='string'))}catch{}
  $('ins-metrics').insertAdjacentHTML('afterend','<section id="focus-priorities" class="focus-section"><div class="focus-section-heading"><div><span class="focus-eyebrow">ТОЧКИ КОНТРОЛЯ</span><h2>Что проверить в первую очередь</h2><p>По выбранному периоду и текущему состоянию товаров</p></div><button class="button secondary" id="focus-favorites">★ Избранное</button></div><div id="focus-alerts" class="focus-alerts"></div></section>');
  $('ins-state').insertAdjacentHTML('afterend','<section id="focus-brief" class="focus-brief"></section>');
  const section=$('ins-stores').closest('section'),heading=section.querySelector('.panel-heading');heading.id='focus-stores';heading.insertAdjacentHTML('afterend','<div id="focus-store-grid" class="focus-store-grid"></div>');
  const wrap=$('ins-stores').closest('.table-wrap'),details=document.createElement('details');details.className='focus-store-details';details.innerHTML='<summary>Подробная таблица магазинов</summary>';wrap.before(details);details.append(wrap);
  $('ins-products-panel').querySelector('.panel-heading').insertAdjacentHTML('afterend','<div id="focus-abc" class="focus-abc"></div>');
  $('focus-alerts').onclick=e=>{const b=e.target.closest('[data-focus-filter]');if(b)selectFilter(b.dataset.focusFilter)};
  $('focus-favorites').onclick=()=>selectFilter('favorites');
  $('focus-store-grid').onclick=e=>{const b=e.target.closest('[data-focus-store]');if(b)selectStore(b.dataset.focusStore)};
  $('focus-abc').onclick=e=>{const b=e.target.closest('[data-focus-abc]');if(b)selectFilter(b.dataset.focusAbc)};
  function renderBrief(){
   const lead=model.stores.find(s=>s.complete&&s.realized>0),a=model.groups[0],snap=report.intraday?.orders||[],last=snap.at(-1),prev=snap.at(-2),change=prev?last.orderedRevenue-prev.orderedRevenue:null;
   const facts=[['Лидер по реализации',model.complete&&lead?esc(lead.name):'Ожидаем полный период',model.complete&&lead?money(lead.realized)+(lead.share===null?'':' · '+dec.format(lead.share)+'% общей реализации'):'Учитываются все выбранные магазины'],['Главные товары',model.complete&&model.positiveRealized>0?n.format(a.count)+' SKU в группе A':'—',model.complete&&model.positiveRealized>0?dec.format(a.share)+'% положительной реализации':'ABC появится после загрузки финансов'],report.days===1?['Последнее изменение заказов',change===null?'Накапливаем историю':(change>0?'+':'')+money(change),change===null?'Заказы запрашиваются каждые 5 минут':'Между двумя последними загрузками за выбранный день']:['Концентрация реализации',model.complete&&model.positiveRealized>0?dec.format(model.top10Share)+'% у топ-10 SKU':'—','Доля в положительной реализации SKU за период']];
   $('focus-brief').innerHTML='<div class="focus-brief-top"><span>ПУЛЬС БИЗНЕСА</span><a href="#focus-priorities">Перейти к проверкам ↓</a></div><div class="focus-facts">'+facts.map(([label,value,note])=>'<div><span>'+label+'</span><strong>'+value+'</strong><small>'+note+'</small></div>').join('')+'</div>';
  }
  function renderAlerts(){
   $('focus-alerts').innerHTML=Object.entries(rules).map(([key,[title,description,tag]])=>'<button class="focus-alert" data-focus-filter="'+key+'" '+(model.alerts[key]===null?'disabled':'')+' title="'+esc(description)+'"><span class="focus-tag">'+tag+'</span><strong>'+ (model.alerts[key]===null?'—':n.format(model.alerts[key]))+' <small>SKU</small></strong><b>'+title+'</b><p>'+description+'</p><span class="focus-open">Открыть список →</span></button>').join('');
   $('focus-favorites').textContent='★ Избранное · '+model.products.filter(p=>favorites.has(p.focusId)).length;
  }
  function renderStores(){
   $('focus-store-grid').innerHTML=model.stores.map((s,i)=>'<button class="focus-store" data-focus-store="'+esc(s.id)+'"><span class="focus-store-top"><b>'+esc(s.name)+'</b><span>'+(s.complete?'Ozon':'Неполный период')+'</span></span><strong>'+ (s.complete?money(s.realized):'—')+'</strong><span class="focus-store-sub">Реализация'+(s.share===null?'':' · '+dec.format(s.share)+'% общей')+'</span><div class="focus-share"><i style="width:'+(s.share??0)+'%;--store-color:'+['#5377ed','#43a38e','#9978d8','#d3a05b'][i%4]+'"></i></div><dl>'+['commission','logistics','ads','net'].map((key,j)=>'<div><dt>'+['Комиссия','Логистика','Реклама','Начисления'][j]+'</dt><dd>'+(s.per100?dec.format(s.per100[key])+' ₽':'—')+'</dd></div>').join('')+'</dl><span class="focus-store-sub">На каждые 100 ₽ реализации · начисления не равны прибыли</span><span class="focus-open">Открыть магазин →</span></button>').join('');
  }
  function renderABC(){
   $('focus-abc').innerHTML='<div><b>ABC-анализ по реализации SKU</b><p>A — первые ~80% реализации, B — следующие ~15%, C — остаток. SKU на границе входит в предыдущую группу. SKU с итоговой реализацией ≤ 0 не участвуют.</p></div><div class="focus-abc-groups">'+model.groups.map(g=>'<button data-focus-abc="'+g.group+'" '+(!model.complete?'disabled':'')+'><span class="focus-grade grade-'+g.group+'">'+g.group+'</span><strong>'+(model.complete?n.format(g.count)+' SKU':'—')+'</strong><small>'+(model.complete?dec.format(g.share)+'% реализации':'Нет полного периода')+'</small></button>').join('')+'</div>';
  }
  function render(value){report=value;model=PultFocus.build(value);renderBrief();renderAlerts();renderStores();renderABC();return model}
  function favoriteButton(p){const on=favorites.has(p.focusId);return '<button class="focus-star '+(on?'selected':'')+'" data-focus-favorite="'+esc(p.focusId)+'" aria-pressed="'+on+'" aria-label="'+(on?'Убрать из избранного':'В избранное')+': '+esc(p.name)+'">'+(on?'★':'☆')+'</button>'}
  function toggleFavorite(id){if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem('pult-favorite-skus-v1',JSON.stringify([...favorites]))}catch{}renderAlerts()}
  function detail(id){const p=model.products.find(p=>p.focusId===id);if(!p)return;const signals=p.signals.map(key=>'<li>'+esc(rules[key][1])+'</li>').join('');$('ins-detail-content').innerHTML='<span class="focus-grade grade-'+p.abc+'">'+p.abc+'</span><h2 class="detail-title">'+esc(p.name)+'</h2><p>'+esc(p.storeName)+' · '+esc(p.offer_id)+' · SKU '+esc(p.sku)+'</p><div class="detail-grid">'+[['Реализация за период',money(p.realized)],['Начисления по SKU',money(p.net)],['Доля реализации SKU',dec.format(p.share)+'%'],['Комиссия',money(p.commission)],['Логистика',money(p.logistics)],['Текущий остаток',p.quantity===null?'Неизвестен':n.format(p.quantity)+' шт.'],['Текущая себестоимость',p.cost>0?money(p.cost,p.costCurrency):'Не заполнена']].map(([k,v])=>'<div class="detail-item"><span>'+k+'</span><strong>'+v+'</strong></div>').join('')+'</div>'+(signals?'<ul class="focus-detail-signals">'+signals+'</ul>':'')+'<p>ABC и суммы относятся к '+esc(report.current.from)+' — '+esc(report.current.to)+'. Начисления по SKU не равны прибыли. Общие расходы магазина могут не иметь привязки к товару.</p>'+(p.key?'<p><a class="button" href="/manage.html?product='+encodeURIComponent(p.key)+'">Открыть цену и заметки →</a></p>':'<p>Карточки нет в текущем каталоге.</p>');$('ins-detail').showModal()}
  return {render,toggleFavorite,favoriteButton,detail,get favorites(){return favorites},get model(){return model}};
 }};
})();
